{
  "up": "Select m.chembl_id AS molecule_chembl_id, m.pref_name AS molecule_name, m.max_phase AS max_phase, m.molecule_type AS molecule_type, cs.canonical_smiles AS canonical_smiles From molecule_dictionary m Join compound_records r ON m.molregno = r.molregno Join docs d ON r.doc_id = d.doc_id Left Join compound_structures cs ON m.molregno = cs.molregno Where d.chembl_id = 'CHEMBL5303573' Sort By molecule_chembl_id"
}
